// === Zentrale Konfiguration – hier pflegen ===
const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  // Zeitraum der Bearbeitung (nicht des Bestelldatums!).
  // updatedAtMin gesetzt -> gewinnt. Sonst wird stundenZurueck verwendet.
  updatedAtMin: null,
  updatedAtMax: null,
  stundenZurueck: 24,

  // Nach App-Name filtern. Beim ERSTEN Lauf auf null lassen – dann siehst du
  // im Ergebnis, wie deine App in appTitle heisst, und kannst hier eintragen.
  appTitel: null,

  // Zusätzlich nach Event-Text suchen (staffNote aus orderEditCommit).
  // null = nur nach App filtern.
  suchtext: 'Automatischer Positionstausch',

  // Verknüpfung der beiden Filter: 'ODER' (Treffer bei einem von beiden)
  // oder 'UND' (beide müssen zutreffen).
  verknuepfung: 'ODER',

  // Schutz gegen Endlosschleife bei sehr grossen Zeiträumen
  maxSeiten: 25
};

const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
staticData.treffer = [];
staticData.geprueft = 0;
staticData.appTitelGesehen = {};

return [{ json: { config: CONFIG } }];

const config = $('Config').first().json.config;

// Zeitfenster bestimmen
let min = config.updatedAtMin;
if (!min) {
  const h = Number(config.stundenZurueck) || 24;
  min = new Date(Date.now() - h * 3600 * 1000).toISOString();
}

const staticData = $getWorkflowStaticData('global');
staticData.treffer = [];
staticData.geprueft = 0;
staticData.appTitelGesehen = {};
staticData.updatedAtMin = min;

return [{ json: { cursor: null, hasNext: true, seite: 0, updatedAtMin: min } }];

const config = $('Config').first().json.config;
const inp = $input.first().json;
const staticData = $getWorkflowStaticData('global');

const filter = ['updated_at:>=' + staticData.updatedAtMin];
if (config.updatedAtMax) filter.push('updated_at:<=' + config.updatedAtMax);

// Events tragen attributeToApp + appTitle -> daran erkennt man App-Bearbeitungen.
const body = {
  query: `query($cursor: String, $q: String!) {
    orders(first: 20, after: $cursor, query: $q, sortKey: UPDATED_AT) {
      pageInfo { hasNextPage endCursor }
      edges {
        node {
          id
          name
          createdAt
          updatedAt
          displayFinancialStatus
          app { name }
          totalOutstandingSet { presentmentMoney { amount currencyCode } }
          currentTotalPriceSet { presentmentMoney { amount currencyCode } }
          lineItems(first: 25) {
            edges { node { sku title quantity currentQuantity } }
          }
          events(first: 15, sortKey: CREATED_AT, reverse: true) {
            edges {
              node { id createdAt message attributeToApp attributeToUser appTitle }
            }
          }
        }
      }
    }
  }`,
  variables: { cursor: inp.cursor || null, q: filter.join(' AND ') }
};

return [{
  json: {
    accessToken: $('Token holen').first().json.access_token,
    gqlBody: JSON.stringify(body),
    seite: (Number(inp.seite) || 0) + 1
  }
}];

const resp = $input.first().json;

// GraphQL antwortet mit HTTP 200 auch bei ungültigen Queries
if (resp?.errors?.length) {
  throw new Error('GraphQL: ' + JSON.stringify(resp.errors));
}
const conn = resp?.data?.orders;
if (!conn) {
  throw new Error('Keine orders-Connection erhalten: ' + JSON.stringify(resp));
}

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.treffer)) staticData.treffer = [];
if (!staticData.appTitelGesehen) staticData.appTitelGesehen = {};

const suchtext = config.suchtext ? String(config.suchtext).toLowerCase() : null;
const appTitel = config.appTitel ? String(config.appTitel).toLowerCase() : null;
const undVerknuepft = String(config.verknuepfung || 'ODER').toUpperCase() === 'UND';

for (const edge of conn.edges) {
  const o = edge.node;
  staticData.geprueft = (staticData.geprueft || 0) + 1;

  const events = (o.events?.edges || []).map(e => e.node);

  // Inventar aller gesehenen App-Namen – hilft beim Setzen von Config.appTitel
  for (const ev of events) {
    if (ev.attributeToApp && ev.appTitle) {
      staticData.appTitelGesehen[ev.appTitle] = (staticData.appTitelGesehen[ev.appTitle] || 0) + 1;
    }
  }

  const relevant = events.filter(ev => {
    const trefferApp = ev.attributeToApp === true &&
      (!appTitel || String(ev.appTitle || '').toLowerCase().includes(appTitel));
    const trefferText = suchtext
      ? String(ev.message || '').toLowerCase().includes(suchtext)
      : false;

    if (appTitel && suchtext) {
      return undVerknuepft ? (trefferApp && trefferText) : (trefferApp || trefferText);
    }
    if (suchtext && !appTitel) {
      return undVerknuepft ? (trefferApp && trefferText) : (trefferApp || trefferText);
    }
    return trefferApp;
  });

  if (!relevant.length) continue;

  const li = (o.lineItems?.edges || []).map(e => e.node);
  const aktiv = li.filter(x => Number(x.currentQuantity) > 0);
  const entfernt = li.filter(x => Number(x.currentQuantity) === 0);

  staticData.treffer.push({
    orderName: o.name,
    orderId: o.id.split('/').pop(),
    erstelltAm: o.createdAt,
    bearbeitetAm: o.updatedAt,
    finanzstatus: o.displayFinancialStatus,
    erstelltVonApp: o.app?.name || null,
    offenerSaldo: o.totalOutstandingSet?.presentmentMoney?.amount || null,
    aktuelleSumme: o.currentTotalPriceSet?.presentmentMoney?.amount || null,
    waehrung: o.currentTotalPriceSet?.presentmentMoney?.currencyCode || null,
    aktiveSkus: aktiv.map(x => x.sku).filter(Boolean).join(' | '),
    entfernteSkus: entfernt.map(x => x.sku).filter(Boolean).join(' | '),
    anzahlEvents: relevant.length,
    apps: [...new Set(relevant.map(e => e.appTitle).filter(Boolean))].join(' | '),
    events: relevant
      .map(e => `${e.createdAt} [${e.appTitle || (e.attributeToUser ? 'Mitarbeiter' : 'System')}] ${e.message}`)
      .join(' || ')
  });
}

const seite = Number($('Query bauen (Orders + Events)').first().json.seite) || 1;
const weiter = conn.pageInfo?.hasNextPage === true && seite < Number(config.maxSeiten);

return [{
  json: {
    cursor: conn.pageInfo?.endCursor || null,
    hasNext: weiter,
    seite,
    geprueftGesamt: staticData.geprueft,
    trefferGesamt: staticData.treffer.length
  }
}];

const staticData = $getWorkflowStaticData('global');
const treffer = staticData.treffer || [];
const gesehen = staticData.appTitelGesehen || {};

// === NUR n8n-App-Bearbeitungen ===
// Events sind als "... [appTitle] message" gespeichert -> darauf filtern.
const N8N = 'n8n';
const nurN8n = treffer
  .map(t => {
    const eigene = String(t.events || '')
      .split(' || ')
      .filter(e => e.toLowerCase().includes('[' + N8N));
    if (!eigene.length) return null;
    return {
      ...t,
      anzahlEvents: eigene.length,
      apps: [...new Set(
        String(t.apps || '').split(' | ').filter(a => a.toLowerCase().includes(N8N))
      )].join(' | '),
      events: eigene.join(' || ')
    };
  })
  .filter(Boolean);

const kopf = {
  zeile: 'ZUSAMMENFASSUNG',
  zeitraumAb: staticData.updatedAtMin,
  bestellungenGeprueft: staticData.geprueft || 0,
  treffer: nurN8n.length,
  // Alle App-Namen, die im Zeitraum Events erzeugt haben – zum Setzen von Config.appTitel
  appsImZeitraum: Object.entries(gesehen)
    .sort((a, b) => b[1] - a[1])
    .map(([name, n]) => `${name} (${n})`)
    .join(' | ') || 'keine'
};

if (!nurN8n.length) {
  return [{ json: { ...kopf, hinweis: 'Keine Bestellung mit n8n-App-Bearbeitung gefunden.' } }];
}

// Neueste Bearbeitung zuerst
nurN8n.sort((a, b) => String(b.bearbeitetAm).localeCompare(String(a.bearbeitetAm)));

return [
  { json: kopf },
  ...nurN8n.map(t => ({ json: { zeile: 'BESTELLUNG', ...t } }))
];
